-- AUD-04 (audit top app, 15/11/2026): the collective calendar never runs dry. The only seeded expedition ("automne-2026") ends on
-- 16/11/2026 and seasons, common quests and world goals only exist when an administrator remembers to create them. This migration adds
-- an idempotent "live ops" filler that keeps the next weeks covered from a rotation of written templates:
--   * one common quest per week (Monday to Sunday, Paris time);
--   * seasons of 28 days, back to back;
--   * expeditions of 6 weeks, back to back;
--   * world goals of 12 weeks, back to back.
-- It ONLY fills empty periods: anything an administrator created is never modified, moved or overlapped (the same overlap rules as the
-- admin RPCs: seasons and world goals never overlap, a week has one common quest, an expedition never overlaps a published one).
-- Nothing here grants XP, credits or rankings: these events keep their existing rules (normalized effort, 90 min per day, join on purpose).
-- Rows are created with created_by = null (system). A weekly pg_cron job keeps 12 weeks ahead; it is skipped when pg_cron is absent.
-- NOT APPLIED automatically: the owner applies it with the release sequence, then may run once
--   select private.titan_event_calendar_fill_v1(12);
-- to cover the current weeks immediately (otherwise the first weekly cron run, Monday 03:50 UTC, does it).
-- Targets are deliberately modest for a young community; edit the template arrays before applying if the audience is larger.
-- Additive. The caller owns the transaction: never BEGIN/COMMIT here.
-- Rollback: select cron.unschedule('titan_event_calendar_fill') (if scheduled); drop function private.titan_event_calendar_fill_v1(integer);
-- rows created by the filler can be found with created_by is null and id like 'auto-%' (expeditions) and deleted while unused.

create or replace function private.titan_event_calendar_fill_v1(p_weeks integer default 12)
returns jsonb
language plpgsql
security definer
set search_path = public, private, pg_temp
set statement_timeout = '20s'
as $$
declare
  v_weeks integer := least(greatest(coalesce(p_weeks, 12), 1), 26);
  v_monday date := (date_trunc('week', now() at time zone 'Europe/Paris'))::date;
  v_until date;
  d date;
  e date;
  nxt date;
  v_end timestamptz;
  i integer;
  n_quests integer := 0;
  n_seasons integer := 0;
  n_expeditions integer := 0;
  n_goals integer := 0;
  -- Common quests of the week: title, detail, target in normalized effort minutes (all sports equal, 90 min per day and per person).
  q_title text[] := array[
    'La semaine des premiers pas', 'Chacun son sport, un seul objectif', 'La semaine des retours', 'Ensemble, sans exploit',
    'La semaine des variantes', 'Le relais du dimanche', 'La semaine des régulières', 'Le feu de camp collectif'];
  q_detail text[] := array[
    'Une séance courte compte autant qu’une longue : chaque minute d’effort, dans ton sport, fait avancer tout le monde.',
    'Course, muscu, escalade, natation ou yoga : tout se compte en minutes d’effort, à égalité.',
    'Tu reviens après une pause ? Cette semaine est faite pour toi. Aucune séance n’est trop petite.',
    'Pas de record à battre : seulement la somme de nos efforts, 90 minutes au plus par jour et par personne.',
    'Essaie un autre sport que d’habitude, ou garde le tien : toutes les familles comptent pareil.',
    'Chaque jour de la semaine compte : le dimanche soir, on regarde ensemble ce qu’on a construit.',
    'Tenir sa semaine type suffit. La régularité de chacun fait la force du groupe.',
    'Chaque séance ajoute une bûche au feu. Rejoins la quête et regarde-le grandir.'];
  q_target integer[] := array[1200, 1500, 1000, 1500, 1200, 1500, 1200, 1500];
  -- Seasons of 28 days, one per world of the bible (docs/V13_WORLD_BIBLE.md), in rotation.
  s_name text[] := array['Saison de l’Aube', 'Saison des Marées', 'Saison d’Obsidienne', 'Saison des Aurores'];
  s_rules text[] := array[
    'Quatre semaines pour retrouver son élan. Tu participes si tu le choisis ; seules les séances enregistrées après ton inscription comptent, en minutes d’effort, 90 au plus par jour. Le repos ne coûte rien.',
    'Quatre semaines pour explorer à ta façon. Toutes les familles de sport comptent pareil, en minutes d’effort, 90 au plus par jour, à partir de ton inscription. Le repos ne coûte rien.',
    'Quatre semaines pour affiner tes repères. Ton résultat est figé à la fin de la saison ; seules les séances enregistrées après ton inscription comptent, 90 minutes au plus par jour.',
    'Quatre semaines pour construire sur la durée. Participation libre, minutes d’effort comptées à partir de ton inscription, 90 au plus par jour, sans pénalité pour le repos.'];
  -- Expeditions of 6 weeks.
  x_title text[] := array['La veillée du givre', 'Les feux du renouveau', 'La crue des marées', 'La route des lucioles', 'Le soufflet des cimes', 'Les cols de l’aurore'];
  x_story text[] := array[
    'Quand le givre fige les cols, la Sentinelle du givre ne cède qu’à la constance. Chaque minute d’effort, dans ton sport, rallume un feu de veille. 90 minutes comptent au plus par jour : la régularité passe avant l’exploit.',
    'Après les longues nuits, le Gardien des cendres attend les premiers feux de l’année. Chacun en allume un, à son rythme et dans son sport. 90 minutes comptent au plus par jour.',
    'Au printemps, la Dame des crues fait monter les eaux entre les îles. On ne la combat pas : on construit le passage ensemble, minute après minute. 90 minutes comptent au plus par jour.',
    'Les longues soirées réveillent les lucioles du sentier. La Gardienne des lucioles éclaire le chemin de ceux qui reviennent, séance après séance. 90 minutes comptent au plus par jour.',
    'Au cœur de l’été, le soufflet des forges ne s’arrête jamais. Chaque effort entretient la flamme commune, sans exploit ni pression. 90 minutes comptent au plus par jour.',
    'À la rentrée, les cols de l’aurore se rouvrent pour ceux qui marchent ensemble. Ton sport, ton rythme, une seule montée collective. 90 minutes comptent au plus par jour.'];
  x_guardian text[] := array['La Sentinelle du givre', 'Le Gardien des cendres', 'La Dame des crues', 'La Gardienne des lucioles', 'Le Maître du soufflet', 'Le Veilleur des cols'];
  x_reward text[] := array['Veilleur du givre', 'Porte-flamme', 'Passe-crue', 'Porte-lucioles', 'Attise-braise', 'Éclaireur d’aurore'];
  -- World goals of 12 weeks, three levels so every size of community has something realistic to reach.
  g_title text[] := array['L’ascension de l’hiver', 'L’ascension du printemps', 'L’ascension de l’été', 'L’ascension de l’automne'];
  g_detail text[] := array[
    'Tous ensemble, gravir trois paliers en minutes d’effort. Chacun voit sa part, le total et le nombre de participants ; personne ne voit la part des autres.',
    'Trois paliers à atteindre ensemble, toutes disciplines confondues. Rejoins l’objectif pour que tes séances suivantes y comptent.',
    'Trois paliers, douze semaines, aucune compétition : seulement la somme de nos efforts, 90 minutes au plus par jour et par personne.',
    'Trois paliers pour finir l’année en mouvement. Ta part reste privée ; le total appartient à tout le monde.'];
begin
  -- One filler at a time: two concurrent runs would otherwise both see the same gap.
  perform pg_advisory_xact_lock(hashtext('titan_event_calendar_fill_v1'));
  v_until := v_monday + v_weeks * 7;

  -- 1. Common quests: one per week; a week already planned by an administrator is kept as is.
  for i in 0 .. v_weeks - 1 loop
    d := v_monday + i * 7;
    insert into private.titan_common_quests (week_start, title, detail, target_minutes, created_by)
    values (d, q_title[1 + (extract(week from d)::integer % 8)], q_detail[1 + (extract(week from d)::integer % 8)], q_target[1 + (extract(week from d)::integer % 8)], null)
    on conflict (week_start) do nothing;
    if found then n_quests := n_quests + 1; end if;
  end loop;

  -- 2. Seasons of 28 days, never overlapping an existing one.
  d := v_monday;
  while d < v_until loop
    select s.ends_on into e from private.titan_seasons s where d between s.starts_on and s.ends_on order by s.starts_on limit 1;
    if e is not null then d := e + 1; e := null; continue; end if;
    select min(s.starts_on) into nxt from private.titan_seasons s where s.starts_on > d and s.starts_on <= d + 27;
    if nxt is not null then d := nxt; nxt := null; continue; end if;
    insert into private.titan_seasons (name, rules, starts_on, created_by)
    values (s_name[1 + ((d - date '2026-11-16') / 28 % 4 + 4) % 4], s_rules[1 + ((d - date '2026-11-16') / 28 % 4 + 4) % 4], d, null);
    n_seasons := n_seasons + 1;
    d := d + 28;
  end loop;

  -- 3. Expeditions of 6 weeks, never overlapping a published one. The id carries the start date; the reward title rotates.
  d := v_monday;
  while d < v_until loop
    select max(x.ends_at) into v_end from public.titan_expeditions x
     where x.published and x.starts_at < ((d + 42)::timestamp at time zone 'Europe/Paris') and x.ends_at > (d::timestamp at time zone 'Europe/Paris');
    if v_end is not null then
      e := (v_end at time zone 'Europe/Paris')::date;
      if (v_end at time zone 'Europe/Paris')::time > time '00:00' then e := e + 1; end if;
      d := e + ((8 - extract(isodow from e)::integer) % 7);
      v_end := null;
      continue;
    end if;
    i := 1 + (((d - date '2026-11-16') / 42) % 6 + 6) % 6;
    insert into public.titan_expeditions (id, title, story, guardian, starts_at, ends_at, collective_goal, personal_days, personal_minutes, daily_cap, reward_title, published)
    values ('auto-' || to_char(d, 'YYYY-MM-DD'), x_title[i], x_story[i], x_guardian[i], d::timestamp at time zone 'Europe/Paris', (d + 42)::timestamp at time zone 'Europe/Paris',
            7200, 5, 300, 90, x_reward[i], true)
    on conflict (id) do nothing;
    if found then n_expeditions := n_expeditions + 1; end if;
    d := d + 42;
  end loop;

  -- 4. World goals of 12 weeks (inclusive end on a Sunday), never overlapping an existing one.
  d := v_monday;
  while d < v_until loop
    select max(g.ends_on) into e from private.titan_world_goals g where g.starts_on <= d + 83 and g.ends_on >= d;
    if e is not null then
      d := e + 1;
      d := d + ((8 - extract(isodow from d)::integer) % 7);
      e := null;
      continue;
    end if;
    i := 1 + (((d - date '2026-11-16') / 84) % 4 + 4) % 4;
    insert into private.titan_world_goals (starts_on, ends_on, title, detail, level1, level2, level3, created_by)
    values (d, d + 83, g_title[i], g_detail[i], 5000, 15000, 40000, null);
    n_goals := n_goals + 1;
    d := d + 84;
  end loop;

  return jsonb_build_object('from', v_monday, 'until', v_until, 'commonQuests', n_quests, 'seasons', n_seasons, 'expeditions', n_expeditions, 'worldGoals', n_goals);
end;
$$;

revoke all on function private.titan_event_calendar_fill_v1(integer) from public, anon, authenticated;
grant usage on schema private to service_role;
grant execute on function private.titan_event_calendar_fill_v1(integer) to service_role;

do $schedule$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    if not exists (select 1 from cron.job where jobname = 'titan_event_calendar_fill') then
      perform cron.schedule('titan_event_calendar_fill', '50 3 * * 1', 'select private.titan_event_calendar_fill_v1(12);');
    end if;
  end if;
end $schedule$;
